'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  let prefix = 0;
  while (prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) {
    prefix++;
  }
  let oldEnd = a.length;
  let newEnd = b.length;
  while (oldEnd > prefix && newEnd > prefix && a[oldEnd - 1] === b[newEnd - 1]) {
    oldEnd--;
    newEnd--;
  }

  const result = [];
  for (let i = 0; i < prefix; i++) {
    result.push({ op: 'equal', line: a[i] });
  }
  const n = oldEnd - prefix;
  const m = newEnd - prefix;
  const snakes = [];
  if (n && m) {
    // Frontier slot i at distance d represents diagonal k = 2*i - d.
    // Keep only reachable parity slots, rather than copying an N+M-sized array.
    const trace = [new Int32Array(1)];
    let distance = 0;
    search:
    for (let d = 1; d <= n + m; d++) {
      const previous = trace[d - 1];
      const frontier = new Int32Array(d + 1);
      trace.push(frontier);
      for (let i = 0; i <= d; i++) {
        const k = 2 * i - d;
        let x = i === 0 || (i !== d && previous[i - 1] < previous[i])
          ? previous[i]
          : previous[i - 1] + 1;
        let y = x - k;
        while (x < n && y < m && a[prefix + x] === b[prefix + y]) {
          x++;
          y++;
        }
        frontier[i] = x;
        if (x >= n && y >= m) {
          distance = d;
          break search;
        }
      }
    }

    // Recover matching runs, then emit the gaps as deletes followed by inserts.
    // This preserves each input's order even when Myers interleaves edit types.
    let x = n;
    let y = m;
    for (let d = distance; d > 0; d--) {
      const k = x - y;
      const i = (k + d) / 2;
      const previous = trace[d - 1];
      const insertion = i === 0 || (i !== d && previous[i - 1] < previous[i]);
      const previousX = insertion ? previous[i] : previous[i - 1];
      const previousY = previousX - (insertion ? k + 1 : k - 1);
      const startX = previousX + (insertion ? 0 : 1);
      const startY = previousY + (insertion ? 1 : 0);
      if (x > startX) {
        snakes.push({ x: startX, y: startY, length: x - startX });
      }
      x = previousX;
      y = previousY;
    }
  }

  let old = prefix;
  let next = prefix;
  for (let i = snakes.length - 1; i >= 0; i--) {
    const snake = snakes[i];
    while (old < prefix + snake.x) result.push({ op: 'delete', line: a[old++] });
    while (next < prefix + snake.y) result.push({ op: 'insert', line: b[next++] });
    for (let j = 0; j < snake.length; j++) {
      result.push({ op: 'equal', line: a[old++] });
      next++;
    }
  }
  while (old < oldEnd) result.push({ op: 'delete', line: a[old++] });
  while (next < newEnd) result.push({ op: 'insert', line: b[next++] });
  while (old < a.length) result.push({ op: 'equal', line: a[old++] });
  return result;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isSafeInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);
  const hunks = [];
  let cursor = 0;
  let search = 0;
  let old = 0;
  let next = 0;
  while (search < script.length) {
    while (search < script.length && script[search].op === 'equal') search++;
    if (search === script.length) break;
    const start = Math.max(cursor, search - context);
    let lastChange = search;
    let scan = search + 1;
    for (; scan < script.length; scan++) {
      if (script[scan].op !== 'equal') {
        lastChange = scan;
      } else if (scan - lastChange > 2 * context) {
        break;
      }
    }
    const end = Math.min(script.length, lastChange + context + 1);
    while (cursor < start) {
      // Only unchanged entries can lie between hunk ranges.
      old++;
      next++;
      cursor++;
    }
    const hunk = { oldStart: old + 1, oldLines: 0, newStart: next + 1, newLines: 0, lines: [] };
    while (cursor < end) {
      const entry = script[cursor++];
      if (entry.op !== 'insert') {
        old++;
        hunk.oldLines++;
      }
      if (entry.op !== 'delete') {
        next++;
        hunk.newLines++;
      }
      const marker = entry.op === 'equal' ? ' ' : entry.op === 'delete' ? '-' : '+';
      hunk.lines.push(marker + entry.line);
    }
    if (hunk.oldLines === 0) hunk.oldStart--;
    if (hunk.newLines === 0) hunk.newStart--;
    hunks.push(hunk);
    search = scan;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const result = [];
  let cursor = 0;
  for (let index = 0; index < hunks.length; index++) {
    const hunk = hunks[index];
    const fail = () => { throw new Error(`hunk ${index} does not apply`); };
    if (!hunk || !Array.isArray(hunk.lines) ||
        !Number.isSafeInteger(hunk.oldStart) || !Number.isSafeInteger(hunk.newStart) ||
        !Number.isSafeInteger(hunk.oldLines) || hunk.oldLines < 0 ||
        !Number.isSafeInteger(hunk.newLines) || hunk.newLines < 0) {
      fail();
    }
    const start = hunk.oldLines === 0 ? hunk.oldStart : hunk.oldStart - 1;
    const newStart = hunk.newLines === 0 ? hunk.newStart : hunk.newStart - 1;
    const end = start + hunk.oldLines;
    if (start < cursor || start > a.length || end > a.length ||
        newStart !== result.length + start - cursor) {
      fail();
    }
    while (cursor < start) result.push(a[cursor++]);
    let newLines = 0;
    for (const line of hunk.lines) {
      if (typeof line !== 'string' || line.length === 0) fail();
      const marker = line[0];
      const text = line.slice(1);
      if (marker === ' ' || marker === '-') {
        if (cursor >= end || a[cursor] !== text) fail();
        cursor++;
      } else if (marker !== '+') {
        fail();
      }
      if (marker !== '-') {
        result.push(text);
        newLines++;
      }
    }
    if (cursor !== end || newLines !== hunk.newLines) fail();
  }
  while (cursor < a.length) result.push(a[cursor++]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

