'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Uint32Array(b.length + 1);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const above = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = above;
    }
  }
  return row[b.length];
}

function check(a, b) {
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  let inserted = false;
  for (const entry of script) {
    if (entry.op === 'equal') inserted = false;
    if (entry.op === 'insert') inserted = true;
    if (entry.op === 'delete') assert.equal(inserted, false);
  }
  assert.deepEqual(diffLines(a, b), script);
  for (const context of [0, 1, 2, 3]) {
    const hunks = unifiedHunks(a, b, { context });
    for (const hunk of hunks) {
      Object.freeze(hunk.lines);
      Object.freeze(hunk);
    }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
  }
}

test('exhaustive minimality, ordering, determinism, and patch roundtrips', () => {
  const inputs = [Object.freeze([])];
  let level = [[]];
  for (let length = 1; length <= 4; length++) {
    level = level.flatMap(a => ['', 'a', 'b'].map(line => Object.freeze([...a, line])));
    inputs.push(...level);
  }
  for (const a of inputs) for (const b of inputs) check(a, b);
});

test('zero-length ranges, literal prefixes, context boundaries, and defaults', () => {
  assert.deepEqual(unifiedHunks([], ['+x', '-y', ' z', ''], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 4, lines: ['++x', '+-y', '+ z', '+'] },
  ]);
  assert.deepEqual(unifiedHunks(['x'], [], { context: 0 }), [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] },
  ]);
  assert.deepEqual(unifiedHunks(['a'], ['a', 'b'], { context: 0 }), [
    { oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+b'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a'], { context: 0 }), [
    { oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-b'] },
  ]);
  const a = ['0', '1', '2', '3', '4', '5', '6', '7', '8'];
  const touching = ['0', 'X', '2', '3', 'Y', '5', '6', '7', '8'];
  assert.deepEqual(unifiedHunks(a, touching, { context: 1 }), [{
    oldStart: 1, oldLines: 6, newStart: 1, newLines: 6,
    lines: [' 0', '-1', '+X', ' 2', ' 3', '-4', '+Y', ' 5'],
  }]);
  const separated = ['0', 'X', '2', '3', '4', 'Y', '6', '7', '8'];
  assert.deepEqual(unifiedHunks(a, separated, { context: 1 }), [
    { oldStart: 1, oldLines: 3, newStart: 1, newLines: 3, lines: [' 0', '-1', '+X', ' 2'] },
    { oldStart: 5, oldLines: 3, newStart: 5, newLines: 3, lines: [' 4', '-5', '+Y', ' 6'] },
  ]);
  assert.deepEqual(unifiedHunks(a, separated), [{
    oldStart: 1, oldLines: 9, newStart: 1, newLines: 9,
    lines: [' 0', '-1', '+X', ' 2', ' 3', ' 4', '-5', '+Y', ' 6', ' 7', ' 8'],
  }]);
  check(Object.freeze(['+x', '-y', ' z', '']), Object.freeze([' z', '', '+x', '-y']));
  const copy = applyHunks(a, []);
  assert.deepEqual(copy, a);
  assert.notEqual(copy, a);
  assert.deepEqual(unifiedHunks(a, a), []);
});

test('application validates malformed hunks and original/result coordinates', () => {
  const a = ['a', 'b', 'c'];
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  assert.deepEqual(applyHunks(a, [valid]), ['a', 'B', 'c']);
  for (const bad of [null, {}, { ...valid, lines: null },
    ...['oldStart', 'oldLines', 'newStart', 'newLines'].flatMap(key =>
      [-1, 1.5, NaN, Infinity, '2', undefined].map(value => ({ ...valid, [key]: value }))),
    { ...valid, oldStart: 0 }, { ...valid, oldStart: 5 },
    { ...valid, newStart: 1 }, { ...valid, oldLines: 0 }, { ...valid, newLines: 0 },
    { ...valid, lines: ['-wrong', '+B'] }, { ...valid, lines: [' wrong'] },
    { ...valid, lines: ['?b'] }, { ...valid, lines: [''] }, { ...valid, lines: [42] },
    { ...valid, lines: ['-b', '-c', '+B'] }, { ...valid, lines: ['+B'] },
  ]) assert.throws(() => applyHunks(a, [bad]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  const insertion = { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] };
  assert.throws(() => applyHunks(a, [insertion, valid]), /hunk 1 does not apply/);
  assert.deepEqual(applyHunks(a, [insertion, { ...valid, newStart: 3 }]), ['top', 'a', 'B', 'c']);
  assert.throws(() => applyHunks(a, [valid, insertion]), /hunk 1 does not apply/);
});

test('20,000-line small changes, including repeated lines', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? String(i % 3) : `line ${i}`);
    const b = a.slice();
    b[100] = 'replacement';
    b.splice(10000, 0, 'inserted');
    b.splice(18000, 1);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    assert.deepEqual(applyHunks(a, hunks), b);
    const elapsed = performance.now() - start;
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.ok(elapsed < 1000, `${elapsed}ms`);
    console.log(`20,000 lines (${repetitive ? 'repeated' : 'unique'}): ${elapsed.toFixed(2)}ms`);
  }
});

